function sppAdminToken(){return localStorage.getItem('adminToken')||'';}
async function sppApi(path,options={}){
 const isForm=options.body instanceof FormData;
 const headers={Accept:'application/json',...(isForm?{}:{'Content-Type':'application/json'}),...(sppAdminToken()?{Authorization:`Bearer ${sppAdminToken()}`}:{}) ,...(options.headers||{})};
 const response=await fetch(`${SPP_API_BASE}/api${path}`,{credentials:'same-origin',...options,headers,cache:'no-store'});
 const payload=await response.json().catch(()=>({}));
 if(response.status===401){toast('Your administrator session has expired. Please sign in again.','warn');location.href='Adminlogin.html';throw new Error('Administrator authentication required.');}
 if(!response.ok)throw new Error(payload.error||payload.message||`Request failed (${response.status}).`);
 return payload;
}
function safeImageUrl(value){const v=String(value||'').trim();if(!v)return '';try{const u=new URL(v,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch{return '';}}
async function uploadAdminImage(file){const form=new FormData();form.append('file',file);const result=await sppApi('/admin/upload',{method:'POST',body:form});return result.url||'';}
async function loadManagedPageData(page){
 try{
  if(page==='team'){
   const result=await sppApi('/admin/team');managedTeamRows=Array.isArray(result.data)?result.data:[];
   if(currentPage==='team')renderManagedTeamRows();
  }else if(page==='syfm'){
   const result=await sppApi('/admin/syfm/navigation');syfmSettings={...syfmSettings,...(result.data||{})};
   syfmMenuItems=(syfmSettings.navigation||[]).map(x=>x.label);syfmNewsCategories=[...(syfmSettings.newsCategories||syfmNewsCategories)];
   if(currentPage==='syfm')renderSyfmEditor();
  }else if(page==='news'){
   const [articles,settings]=await Promise.all([sppApi('/admin/news/articles'),sppApi('/admin/syfm/navigation')]);
   managedNewsRows=Array.isArray(articles.data)?articles.data:[];
   if(settings.data?.newsCategories){syfmNewsCategories=[...settings.data.newsCategories];syfmSettings={...syfmSettings,...settings.data};}
   if(currentPage==='news')renderManagedNewsRows();
  }
 }catch(error){toast(error.message||'Unable to load records from the backend.','warn');}
}


