function updateApiIndicators(connected, detail){
 ['apiLiveIndicator','sidebarApiIndicator'].forEach(id=>{const el=document.getElementById(id);if(!el)return;el.classList.toggle('is-live',!!connected);el.classList.toggle('is-offline',!connected);el.title=detail;el.setAttribute('aria-label',detail);});
}
async function checkApiHealth(){
 const cfg=window.SPP_CONFIG||{};
 const base=String(cfg.API_BASE_URL||'').replace(/\/$/,'');
 const path=String(cfg.API_HEALTH_PATH||'/api/health');
 const url=`${base}${path.startsWith('/')?path:`/${path}`}`;
 try{
  const response=await fetch(url,{method:'GET',credentials:'include',cache:'no-store',headers:{Accept:'application/json'}});
  if(!response.ok)throw new Error(`Health check returned ${response.status}`);
  const type=response.headers.get('content-type')||'';
  let payload={};
  if(type.includes('application/json'))payload=await response.json();
  const healthy=payload.ok===true||payload.healthy===true||['ok','healthy','live'].includes(String(payload.status||'').toLowerCase());
  if(!healthy)throw new Error('Backend did not report a healthy status');
  updateApiIndicators(true,'Backend connection active');
 }catch(error){
  updateApiIndicators(false,'Backend connection not verified');
 }
}

