function kpi(label,value,delta,icon,color='gold',foot='vs previous period'){
 return `<div class="card kpi"><div class="kpi-top"><span class="kpi-label">${label}</span><span class="kpi-icon ${color}">${icon}</span></div><div class="kpi-value">${value}</div><div class="kpi-foot"><span class="trend">↗ ${delta}</span><span>${foot}</span></div>${spark()}</div>`;
}
function lineChart(range='7d',multi=true){
 const sets=range==='24h'?['00','04','08','12','16','20','24']:range==='30d'?Array.from({length:10},(_,i)=>`D${i*3+1}`):range==='12m'?['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']:['Oct 25','Oct 26','Oct 27','Oct 28','Oct 29','Oct 30','Oct 31'];
 const s1=sets.map((_,i)=>42+Math.sin(i*1.1)*13+i*1.1+(i%3)*2),s2=sets.map((_,i)=>24+Math.cos(i*.85)*7+i*.6),s3=sets.map((_,i)=>15+Math.sin(i*.7+1)*5+i*.25);
 const max=85, x=i=>38+i*(660/(sets.length-1)), y=v=>186-v/max*160;
 const poly=a=>a.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
 const labels=sets.map((s,i)=>`<text x="${x(i)}" y="210" fill="#75838a" font-size="9" text-anchor="middle">${s}</text>`).join('');
 const grids=[0,20,40,60,80].map(v=>`<g><line x1="35" y1="${y(v)}" x2="700" y2="${y(v)}" stroke="#273138" stroke-dasharray="3 5"/><text x="25" y="${y(v)+3}" fill="#6e7b82" font-size="8" text-anchor="end">${v}k</text></g>`).join('');
 return `<svg viewBox="0 0 720 225" role="img" aria-label="Website and media performance chart">${grids}<polyline points="${poly(s1)}" fill="none" stroke="#4c8cf5" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${poly(s2)}" fill="none" stroke="#76d94e" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${multi?`<polyline points="${poly(s3)}" fill="none" stroke="#bd8aef" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>`:''}${s1.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#4c8cf5"/>`).join('')}${labels}</svg>`;
}
