function website(){
 const palette=[['header','▤ Header'],['hero','▣ Hero banner'],['text','T Text'],['image','▧ Image'],['video','▷ Video'],['audio','♫ Audio'],['section','▦ Section'],['page','▣ Page break'],['cards','▦ Cards'],['columns','▥ Columns'],['rows','☷ Rows'],['gallery','▧ Gallery'],['news','▤ News feed'],['blog','▤ Blog'],['articles','▤ Articles'],['document','▧ Document'],['social','◎ Social links'],['link','↗ URL link'],['comments','☷ Comments'],['reactions','♥ Reactions'],['footer','▤ Footer']];
 const selected=builderSections.find(x=>x.id===selectedSection)||builderSections[0];
 const align=selected?.align||'centre';
 const sectionHtml=builderSections.map(s=>builderSectionMarkup(s)).join('');
 return `${header('Website & Page Builder','Build complete pages with rich text, media, reusable blocks, post engagement and responsive previews.',`<button class="btn" data-action="builder-preview">◉ Preview</button><button class="btn" data-action="builder-save">Save draft</button><button class="btn primary" data-action="builder-publish">Publish ↗</button>`)}${demoNote('Rich editing, block insertion, local media preview and social interactions work in this browser prototype. Drafts remain local; live publishing and public engagement require connected backend services.')}<div class="builder-layout builder-layout-expanded"><aside class="builder-panel"><div class="panel-title">Add elements <span>＋</span></div><div class="component-list component-list-grid">${palette.map(p=>`<button class="component-btn" data-add-section="${p[0]}">${p[1]}</button>`).join('')}</div><div class="panel-title">Page structure <span>${builderSections.length}</span></div><div class="component-list">${builderSections.map(x=>`<button class="component-btn ${selectedSection===x.id?'component-active':''}" data-select-section="${x.id}">⠿ ${escapeHtml(x.type)} <span style="margin-left:auto;color:#78858b">↕</span></button>`).join('')}</div></aside>
 <section class="builder-canvas"><div class="canvas-toolbar"><div><strong style="font-size:10px">Home page</strong><span style="color:#839097;font-size:9px"> · /</span></div><div class="device-switch"><button data-device="desktop" class="${builderDevice==='desktop'?'selected':''}">Desktop</button><button data-device="tablet" class="${builderDevice==='tablet'?'selected':''}">Tablet</button><button data-device="mobile" class="${builderDevice==='mobile'?'selected':''}">Mobile</button></div></div>
 <div class="editor-toolbar" aria-label="Text formatting toolbar"><button type="button" data-builder-format="bold" title="Bold"><b>B</b></button><button type="button" data-builder-format="italic" title="Italic"><i>I</i></button><button type="button" data-builder-format="underline" title="Underline"><u>U</u></button><span class="toolbar-separator"></span><select class="select editor-select" id="builderFont"><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Verdana">Verdana</option><option value="Times New Roman">Times New Roman</option><option value="Trebuchet MS">Trebuchet MS</option><option value="Courier New">Courier New</option></select><select class="select editor-select" id="builderFontSize"><option value="1">10px</option><option value="2">13px</option><option value="3" selected>16px</option><option value="4">18px</option><option value="5">24px</option><option value="6">32px</option><option value="7">40px</option></select><span class="toolbar-separator"></span><button type="button" data-builder-format="justifyLeft" title="Align left">⇤</button><button type="button" data-builder-format="justifyCenter" title="Centre">↔</button><button type="button" data-builder-format="justifyRight" title="Align right">⇥</button><button type="button" data-builder-format="insertUnorderedList" title="Bullet list">☷</button><button type="button" data-builder-format="createLink" title="Insert URL">↗</button></div>
 <div class="site-preview ${builderDevice}"><div class="site-nav"><b>◉ SHOTO POINT</b>${siteNavMarkup()}</div>${sectionHtml}<div class="site-footer">SHOTO POINT PRODUCTION · Film · Television · Storytelling</div></div></section>
 <aside class="builder-panel properties-panel"><div class="panel-title">Block properties</div>${selected?`<div class="property-form"><label>Block heading<input class="field" id="propTitle" value="${escapeAttr(selected.title||'')}" /></label><label>Text alignment<select class="select" id="propAlign">${contentAlignments.map(a=>`<option ${align===a?'selected':''}>${a}</option>`).join('')}</select></label><label>Destination URL<input class="field" id="propUrl" value="${escapeAttr(selected.url||'')}" placeholder="https://..." /></label><label>Media source URL<input class="field" id="propMediaUrl" value="${escapeAttr(selected.mediaUrl||'')}" placeholder="Optional media URL" /></label>${selected.type==='social'?`<label>Social links (label=https://url, comma separated)<textarea class="field" id="propSocialLinks" placeholder="Instagram=https://instagram.com, YouTube=https://youtube.com">${escapeHtml(selected.socialLinksText||'')}</textarea></label>`:''}<div class="property-actions"><button class="btn" data-action="builder-attach-media">＋ Attach image / video / audio</button><button class="btn" data-action="builder-insert-social">◎ Add social links</button></div><div class="property-actions"><button class="btn" data-action="move-section" data-dir="up">↑ Move up</button><button class="btn" data-action="move-section" data-dir="down">↓ Move down</button><button class="btn danger" data-action="delete-section">Delete block</button></div><small style="color:#738087;line-height:1.5">Edit text directly in the page preview. Select text, then use the formatting toolbar. Use the controls above to attach local media and set block alignment or links.</small></div>`:`<div class="empty-state">Select a block to edit its properties.</div>`}</aside></div>
 <section class="card section-card" style="margin-top:15px"><div class="card-head"><div><h3>Page-level settings</h3><p>Reusable page elements and social sharing</p></div><span class="status">LOCAL DRAFT</span></div><div class="section-body grid three-col"><div><b>Header & navigation</b><p class="helper-text">Add or edit the global header, menu and logo area.</p><button class="btn" data-add-section="header">Add header block</button></div><div><b>Footer & social links</b><p class="helper-text">Add the footer, social icons and contact links.</p><button class="btn" data-add-section="footer">Add footer block</button></div><div><b>Page structure</b><p class="helper-text">Insert a new page or reusable section.</p><button class="btn" data-add-section="page">Add page block</button></div></div></section>`;
}
function builderSectionMarkup(s){
 const body=s.bodyHtml?sanitizeRichHtml(s.bodyHtml):escapeHtml(s.body||'').replace(/\n/g,'<br>');
 const alignment=alignmentCss(s.align||'centre');
 const title=`<h2 class="builder-edit-title" data-builder-title="${s.id}" contenteditable="true" spellcheck="true">${s.titleHtml?sanitizeRichHtml(s.titleHtml):escapeHtml(s.title||'Untitled block')}</h2>`;
 const rich=`<div class="builder-rich-body" data-builder-edit="${s.id}" contenteditable="true" spellcheck="true">${body}</div>`;
 const media=s.mediaUrl? (s.mediaType==='video'?`<video controls playsinline src="${escapeAttr(s.mediaUrl)}" style="max-width:100%"></video>`:s.mediaType==='audio'?`<audio controls src="${escapeAttr(s.mediaUrl)}"></audio>`:`<img src="${escapeAttr(s.mediaUrl)}" alt="${escapeAttr(s.title||'Page image')}" style="max-width:100%;border-radius:8px"/>`):'';
 let content='';
 switch(s.type){
  case 'hero': content=`${title}${rich}<button class="site-cta">${escapeHtml(s.button||'Explore')}</button>${media}`;break;
  case 'image': content=`${title}${media||`<div class="builder-placeholder">Image block · Attach an image from the properties panel</div>`}${rich}`;break;
  case 'video': content=`${title}${media||`<div class="builder-placeholder">Video block · Attach a video to enable playback</div>`}${rich}`;break;
  case 'audio': content=`${title}${media||`<div class="builder-placeholder">Audio block · Attach an audio file</div>`}${rich}`;break;
  case 'gallery': content=`${title}<div class="sample-cards"><div></div><div></div><div></div></div>${rich}`;break;
  case 'cards': case 'columns': case 'rows': content=`${title}${rich}<div class="sample-cards ${s.type==='rows'?'sample-rows':''}"><div>Card one</div><div>Card two</div><div>Card three</div></div>`;break;
  case 'news': case 'blog': case 'articles': content=`${title}${rich}<div class="post-grid">${renderEngagementPost(`${s.id}-1`,s.type==='news'?'Latest newsroom story':'Featured SPP story')}${renderEngagementPost(`${s.id}-2`,'Behind the production')}</div>`;break;
  case 'comments': case 'reactions': content=`${title}${rich}${renderEngagementPost(`${s.id}-community`,'Community conversation')}`;break;
  case 'social': {const links=(s.socialLinksText||'Instagram=#, Facebook=#, YouTube=#, TikTok=#').split(',').map(x=>{const [label,...url]=x.trim().split('=');return {label:label||'Social',url:url.join('=').trim()||'#'};});content=`${title}${rich}<div class="social-links-preview">${links.map((x,i)=>`<a href="${escapeAttr(x.url)}" target="_blank" rel="noopener">${['◎','f','▶','♪','in'][i%5]} ${escapeHtml(x.label)}</a>`).join('')}</div>`;break;}
  case 'link': content=`${title}${rich}<a class="site-cta" href="${escapeAttr(s.url||'#')}" target="_blank" rel="noopener">Open link ↗</a>`;break;
  case 'document': content=`${title}<div class="document-preview">▤ <a href="${escapeAttr(s.mediaUrl||'#')}" target="_blank" rel="noopener">${escapeHtml(s.fileName||'Production document')}</a><span>Document attachment</span></div>${rich}`;break;
  case 'header': content=`<div class="site-header-block"><strong>◉ SHOTO POINT PRODUCTION</strong><nav>Home　 About　 Production　 News　 Contact</nav></div>${title}${rich}`;break;
  case 'footer': content=`${title}${rich}<div class="social-links-preview"><a href="#">◎ Instagram</a><a href="#">f Facebook</a><a href="#">▶ YouTube</a></div>`;break;
  case 'page': content=`<div class="page-break-label">NEW PAGE / ${escapeHtml(s.title||'Untitled page')}</div>${title}${rich}`;break;
  default: content=`${title}${rich}${media}`;
 }
 return `<section class="site-section ${selectedSection===s.id?'selected':''} ${s.type==='hero'?'hero-block':s.type==='text'?'text-block':s.type==='cards'?'cards-block':''}" data-section="${s.id}" style="text-align:${alignment.text};justify-content:${alignment.vertical};">${content}<span class="selected-badge">${escapeHtml(s.type).toUpperCase()}</span></section>`;
}
function alignmentCss(value){const map={'left':{text:'left',vertical:'center'},'right':{text:'right',vertical:'center'},'top':{text:'center',vertical:'flex-start'},'bottom':{text:'center',vertical:'flex-end'},'top right':{text:'right',vertical:'flex-start'},'top left':{text:'left',vertical:'flex-start'},'centre':{text:'center',vertical:'center'},'bottom left':{text:'left',vertical:'flex-end'},'bottom right':{text:'right',vertical:'flex-end'}};return map[value]||map.centre;}
function sanitizeRichHtml(html){
 const doc=new DOMParser().parseFromString(String(html||''),'text/html');
 const allowed=new Set(['B','STRONG','I','EM','U','P','BR','UL','OL','LI','A','SPAN','H2','H3','BLOCKQUOTE','IMG','VIDEO','AUDIO','FONT']);
 [...doc.body.querySelectorAll('*')].forEach(el=>{
  if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);return;}
  [...el.attributes].forEach(a=>{
   const name=a.name.toLowerCase();
   if(name==='style'){
    const styles=[];for(const part of a.value.split(';')){const [k,...v]=part.split(':');const key=(k||'').trim().toLowerCase(),val=v.join(':').trim();if(['font-family','font-size','text-align','color','background-color'].includes(key)&&!/[<>]/.test(val))styles.push(`${key}:${val}`);}if(styles.length)el.setAttribute('style',styles.join(';'));else el.removeAttribute('style');
   }else if(name==='href'&&el.tagName==='A'){if(!/^(https?:|mailto:|tel:|#)/i.test(a.value))el.removeAttribute(a.name);}
   else if(name==='src'&&['IMG','VIDEO','AUDIO'].includes(el.tagName)){if(!/^(https?:|blob:|data:image\/)/i.test(a.value))el.removeAttribute(a.name);}
   else if((name==='alt'&&el.tagName==='IMG')||(name==='face'&&el.tagName==='FONT')||(name==='size'&&el.tagName==='FONT')){}
   else if(name==='controls'&&['VIDEO','AUDIO'].includes(el.tagName)){}
   else if(name==='target'&&el.tagName==='A'){if(a.value!=='_blank')el.removeAttribute(a.name);}
   else if(name==='rel'&&el.tagName==='A'){}
   else el.removeAttribute(a.name);
  });
 });
 return doc.body.innerHTML;
}
function renderEngagementPost(postId,title){
 const stats=postEngagement[postId]||{likes:12,reactions:4,shares:2,comments:3,liked:false};
 return `<article class="post-card" data-post-card="${escapeAttr(postId)}"><div class="post-card-cover">SPP · STORY</div><div class="post-card-body"><strong>${escapeHtml(title)}</strong><p>Discover the people, ideas and stories behind Shoto Point Production.</p><div class="post-stats"><span>${stats.likes} likes</span><span>${stats.reactions||0} reactions</span><span>${stats.comments} comments</span><span>${stats.shares} shares</span></div><div class="post-actions"><button data-post-action="like" data-post-id="${escapeAttr(postId)}" class="${stats.liked?'liked':''}">♥ Like</button><button data-post-action="toggle-comments" data-post-id="${escapeAttr(postId)}">☷ Comment</button><button data-post-action="react" data-post-id="${escapeAttr(postId)}">☺ React</button><button data-post-action="share" data-post-id="${escapeAttr(postId)}">↗ Share</button></div><div class="reaction-picks"><button data-post-action="reaction-love" data-post-id="${escapeAttr(postId)}">❤️ Love</button><button data-post-action="reaction-wow" data-post-id="${escapeAttr(postId)}">😮 Wow</button><button data-post-action="reaction-clap" data-post-id="${escapeAttr(postId)}">👏 Clap</button></div><div class="comment-area" id="comments-${escapeAttr(postId)}" hidden><textarea class="field" data-comment-input="${escapeAttr(postId)}" placeholder="Write a comment..."></textarea><button class="btn primary" data-post-action="submit-comment" data-post-id="${escapeAttr(postId)}">Post comment</button></div></div></article>`;
}


