function media(){const custom=mediaItems.map((m,i)=>({...m,custom:true,index:i}));const items=[...custom,...sampleImages.map((m,i)=>({...m,sampleIndex:i}))];const filtered=items.filter(m=>selectedMediaFilter==='All'||(selectedMediaFilter==='Uploaded'&&m.custom)||(selectedMediaFilter==='Images'&&m.type==='image'));return `${header('Media Library','Manage photographs, artwork, featured images and reusable creative assets.',`<button class="btn" data-action="new-folder">＋ New folder</button><button class="btn primary" data-action="upload-media">↑ Upload media</button>`)}${demoNote('Sample library previews are illustrative. Uploading files here previews them locally in your browser; it does not upload to a server.')}<section class="card"><div class="toolbar"><div class="toolbar-left"><input id="mediaSearch" placeholder="Search media assets..."/><select class="select" id="mediaFilter"><option>All</option><option>Images</option><option>Uploaded</option></select></div><div class="toolbar-right"><span style="color:#87949a;font-size:9px">${items.length} visible assets</span><button class="btn" data-action="upload-media">＋ Add media</button></div></div><div class="media-grid" id="mediaGrid">${filtered.map((m,i)=>`<div class="media-card" data-media-index="${m.custom?'u'+m.index:'s'+m.sampleIndex}" data-media-name="${escapeAttr(m.name)}"><div class="media-thumb">${m.type==='video'?`<video src="${m.src}" poster="${m.poster||''}" muted></video><span class="play">▷</span>`:m.type==='audio'?`<div class="file-thumb">♫<small>AUDIO FILE</small></div>`:m.type==='document'?`<div class="file-thumb">▤<small>DOCUMENT</small></div>`:`<img src="${m.src||'https://images.unsplash.com/photo-1485846234645-a62644f84728?w=900&q=70'}" alt="${escapeAttr(m.name)}" loading="lazy"/>`}</div><div class="media-info"><strong>${escapeHtml(m.name)}</strong><small>${m.type.toUpperCase()} · ${m.size||'Demo file'} · ${m.views||'New'} views</small></div></div>`).join('')}</div></section>`;}
function videos(){return `${header('Video Management','Preview, classify, feature and organise video assets and playlists.',`<button class="btn primary" data-action="upload-media">↑ Upload video</button>`)}${demoNote('The sample player uses a public test video. Production playback, transcoding, CDN delivery and publishing need a connected media backend.')}<div class="grid three-col">${[['Total video views','284.6K'],['Average watch time','04:36'],['Completion rate','64.8%']].map(x=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><small>Illustrative performance</small></div>`).join('')}</div><section class="card section-card" style="margin-top:15px"><div class="card-head"><h3>Video catalogue</h3><span class="status">3 sample videos</span></div><div class="media-grid">${sampleVideos.map((v,i)=>`<div class="media-card" data-video-index="${i}"><div class="media-thumb"><img src="${v.poster}" alt="${escapeAttr(v.name)}"/><span class="play">▷</span></div><div class="media-info"><strong>${v.name}</strong><small>${v.duration} · ${v.views} views · ${v.category}</small></div></div>`).join('')}</div></section><div class="grid two-col"><section class="card"><div class="card-head"><h3>Featured video placement</h3></div><div class="section-body"><div class="quick-row"><span>Homepage hero feature</span><span class="status published">Enabled (demo)</span></div><div class="quick-row"><span>Featured video</span><b>Shoto Point Showreel 2026</b></div><div class="quick-row"><span>Player behavior</span><b>Click to play</b></div><button class="btn" data-action="manage-featured">Configure placement</button></div></section><section class="card"><div class="card-head"><h3>Playlists</h3><button class="btn" data-action="new-playlist">＋ New</button></div><div class="quick-list"><div class="quick-row"><span>Production Showreels</span><b>8 videos</b></div><div class="quick-row"><span>Behind the Scenes</span><b>14 videos</b></div><div class="quick-row"><span>Interviews & Stories</span><b>6 videos</b></div></div></section></div>`;}
function production(){return `${header('Production Hub','Coordinate projects, production stages, crew assignments and deliverables.',`<button class="btn primary" data-action="new-project">＋ New production</button>`)}${demoNote()}<div class="grid four-col">${[['Active productions','08'],['In pre-production','03'],['In post-production','04'],['Delivered this quarter','12']].map(x=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><small>Demo project tracker</small></div>`).join('')}</div><section class="card section-card" style="margin-top:15px"><div class="card-head"><h3>Production pipeline</h3><span class="status">Illustrative projects</span></div><div class="table-wrap"><table class="content-table"><thead><tr><th>Project</th><th>Format</th><th>Producer</th><th>Stage</th><th>Progress</th><th>Due</th></tr></thead><tbody><tr><td>SPP Brand Showreel</td><td>Promotional film</td><td>Production desk</td><td>Post-production</td><td>72%</td><td>Nov 12</td></tr><tr><td>Community Stories</td><td>Documentary series</td><td>Creative team</td><td>Production</td><td>48%</td><td>Nov 20</td></tr><tr><td>Studio Sessions</td><td>Broadcast</td><td>Broadcast desk</td><td>Pre-production</td><td>18%</td><td>Dec 03</td></tr></tbody></table></div></section>`;}
function syfm(){
 const nav=(syfmSettings.navigation||[]).map((item,i)=>`<div class="quick-row" data-syfm-row data-index="${i}" style="gap:8px;flex-wrap:wrap;align-items:center"><span style="color:#d6a52d;min-width:24px">${i+1}.</span><input class="field" data-syfm-label value="${escapeAttr(item.label||'')}" aria-label="Navigation label" style="flex:1;min-width:130px"><input class="field" data-syfm-href value="${escapeAttr(item.href||'#home')}" aria-label="Navigation URL" style="flex:1;min-width:150px"><label style="display:flex;align-items:center;gap:5px;font-size:10px;color:#aeb8bd"><input type="checkbox" data-syfm-enabled ${item.enabled===false?'':'checked'}> Visible</label><button class="btn" type="button" data-syfm-move="up" data-syfm-index="${i}" aria-label="Move ${escapeAttr(item.label)} up">↑</button><button class="btn" type="button" data-syfm-move="down" data-syfm-index="${i}" aria-label="Move ${escapeAttr(item.label)} down">↓</button><button class="btn danger" type="button" data-syfm-remove="${i}">Remove</button></div>`).join('');
 return `${header('SYFM Management','Edit and publish the SYFM website navigation and newsroom categories. Changes are saved to MySQL and appear on the public SYFM website.',`<button class="btn" data-action="syfm-add-menu">＋ Add menu item</button><button class="btn primary" data-action="syfm-save">Save & publish SYFM</button>`)}
 <section class="card section-card"><div class="card-head"><div><h3>SYFM website navigation</h3><p>Control labels, destinations, order and visibility on SYFM(2).html.</p></div><span class="status published">PUBLISHED SETTINGS</span></div><div class="section-body" id="syfmNavigationRows">${nav||'<div class="empty-state">No navigation entries yet. Add a menu item.</div>'}</div><div class="property-form"><label>JOIN SYFM destination<input class="field" id="syfmJoinUrl" value="${escapeAttr(syfmSettings.joinUrl||'MemberShip.html')}" placeholder="MemberShip.html or https://..."></label><label>News categories (one per line)<textarea class="field" id="syfmCategories" rows="6">${escapeHtml((syfmSettings.newsCategories||syfmNewsCategories).join('\n'))}</textarea></label><p class="helper-text">Default categories include All headlines, Nigeria, Politics, Celebrities, Movies & Film, Actors, Musicians, Talents, Football, Media, Tech, World and SPP Originals.</p><div class="property-actions"><button class="btn" data-action="syfm-reset-menu">Restore supplied SYFM menu</button><button class="btn primary" data-action="syfm-save">Save & publish SYFM</button></div></div></section>
 <section class="card section-card"><div class="card-head"><div><h3>Public website preview</h3><p>Changes are published to the SYFM public navigation after saving.</p></div><a class="btn" href="SYFM(2).html" target="_blank" rel="noopener">Open SYFM ↗</a></div><div class="section-body"><div class="site-nav site-nav-admin"><b>SYFM</b><nav class="site-nav-links">${(syfmSettings.navigation||[]).filter(x=>x.enabled!==false).map(x=>`<a class="site-nav-link" href="${escapeAttr(x.href||'#home')}">${escapeHtml(x.label)}</a>`).join('')}<a class="btn primary" href="${escapeAttr(syfmSettings.joinUrl||'MemberShip.html')}">JOIN SYFM ↗</a></nav></div></div></section>`;
}
function renderSyfmEditor(){
 const host=$('#syfmNavigationRows');if(!host)return;
 host.innerHTML=(syfmSettings.navigation||[]).map((item,i)=>`<div class="quick-row" data-syfm-row data-index="${i}" style="gap:8px;flex-wrap:wrap;align-items:center"><span style="color:#d6a52d;min-width:24px">${i+1}.</span><input class="field" data-syfm-label value="${escapeAttr(item.label||'')}" aria-label="Navigation label" style="flex:1;min-width:130px"><input class="field" data-syfm-href value="${escapeAttr(item.href||'#home')}" aria-label="Navigation URL" style="flex:1;min-width:150px"><label style="display:flex;align-items:center;gap:5px;font-size:10px;color:#aeb8bd"><input type="checkbox" data-syfm-enabled ${item.enabled===false?'':'checked'}> Visible</label><button class="btn" type="button" data-syfm-move="up" data-syfm-index="${i}" aria-label="Move ${escapeAttr(item.label)} up">↑</button><button class="btn" type="button" data-syfm-move="down" data-syfm-index="${i}" aria-label="Move ${escapeAttr(item.label)} down">↓</button><button class="btn danger" type="button" data-syfm-remove="${i}">Remove</button></div>`).join('')||'<div class="empty-state">No navigation entries yet. Add a menu item.</div>';
 if($('#syfmJoinUrl'))$('#syfmJoinUrl').value=syfmSettings.joinUrl||'MemberShip.html';
 if($('#syfmCategories'))$('#syfmCategories').value=(syfmSettings.newsCategories||syfmNewsCategories).join('\n');
}
function team(){return `${header('Team Management','Create, edit, publish and remove team profiles. Public team pages read directly from the same database.',`<button class="btn primary" data-action="new-team">＋ Add team profile</button>`)}<section class="card section-card"><div class="card-head"><div><h3>Published team profiles</h3><p>Manage Executive, Administrative and Senior team members.</p></div><span class="status published" id="teamCount">Loading from database…</span></div><div class="table-wrap"><table class="content-table"><thead><tr><th>Profile</th><th>Role</th><th>Group</th><th>Order</th><th>Visibility</th><th>Actions</th></tr></thead><tbody id="teamRecords"><tr><td colspan="6"><div class="empty-state">Loading team records from MySQL…</div></td></tr></tbody></table></div></section><section class="card section-card"><div class="card-head"><div><h3>Public team pages</h3><p>Published profiles are automatically displayed on their matching public team page.</p></div></div><div class="section-body quick-list"><div class="quick-row"><span>Executive team</span><a href="shoto_point_team_pages/ceo.html" target="_blank" rel="noopener">Preview ↗</a></div><div class="quick-row"><span>Administrative team</span><a href="shoto_point_team_pages/administrative.html" target="_blank" rel="noopener">Preview ↗</a></div><div class="quick-row"><span>Senior team</span><a href="shoto_point_team_pages/senior-teams.html" target="_blank" rel="noopener">Preview ↗</a></div></div></section>`;}
function renderManagedTeamRows(){
 const body=$('#teamRecords');if(!body)return;
 const count=$('#teamCount');if(count)count.textContent=`${managedTeamRows.length} DATABASE RECORDS`;
 body.innerHTML=managedTeamRows.length?managedTeamRows.map(m=>`<tr><td><div style="display:flex;align-items:center;gap:9px"><img src="${escapeAttr(safeImageUrl(m.image_url)||'assets/team-placeholder.jpg')}" alt="" style="width:42px;height:42px;object-fit:cover;border-radius:50%"><div><b>${escapeHtml(m.name)}</b><small style="display:block;color:#87949a">${escapeHtml(m.short_bio||'')}</small></div></div></td><td>${escapeHtml(m.role)}</td><td>${escapeHtml(m.group_key)}</td><td>${Number(m.display_order)||0}</td><td><span class="status ${Number(m.active)!==0?'published':'draft'}">${Number(m.active)!==0?'Published':'Hidden'}</span></td><td><button class="btn" data-team-edit="${m.id}">Edit</button> <button class="btn danger" data-team-delete="${m.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state">No team profiles exist in the database yet. Add the first profile to publish it.</div></td></tr>';
}
function openTeamEditor(record=null){
 const m=record||{};
 openModal(record?'Edit team profile':'Add team profile',`<form id="teamProfileForm" class="property-form"><div class="cms-editor-meta"><label>Full name<input class="field" name="name" required value="${escapeAttr(m.name||'')}"></label><label>Role / position<input class="field" name="role" required value="${escapeAttr(m.role||'')}"></label><label>Team group<select class="select" name="group_key"><option value="ceo" ${m.group_key==='ceo'?'selected':''}>Executive</option><option value="administrative" ${m.group_key==='administrative'?'selected':''}>Administrative</option><option value="senior" ${m.group_key==='senior'?'selected':''}>Senior</option></select></label><label>Display order<input class="field" type="number" name="display_order" min="0" value="${Number(m.display_order)||0}"></label></div><label>Short profile<textarea class="field" name="short_bio" rows="2">${escapeHtml(m.short_bio||'')}</textarea></label><label>Full biography<textarea class="field" name="biography" rows="5">${escapeHtml(m.biography||'')}</textarea></label><label>Profile image URL<input class="field" name="image_url" id="teamImageUrl" value="${escapeAttr(m.image_url||'')}" placeholder="Upload an image or paste its URL"></label><label>Upload profile image<input class="field" type="file" name="image_file" id="teamImageFile" accept="image/*"></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="active" ${Number(m.active)===0?'':'checked'}> Publish this profile on the public website</label><div style="display:flex;justify-content:flex-end;gap:8px"><button class="btn" type="button" id="teamCancel">Cancel</button><button class="btn primary" type="submit">${record?'Save changes':'Create & publish profile'}</button></div></form>`,'TEAM PROFILE');
 $('#teamCancel').addEventListener('click',closeModal);
 $('#teamProfileForm').addEventListener('submit',async e=>{
  e.preventDefault();const form=e.currentTarget,fd=new FormData(form);const file=$('#teamImageFile').files[0];
  const body={name:String(fd.get('name')||'').trim(),role:String(fd.get('role')||'').trim(),group_key:fd.get('group_key'),display_order:Number(fd.get('display_order')||0),short_bio:String(fd.get('short_bio')||''),biography:String(fd.get('biography')||''),image_url:$('#teamImageUrl').value.trim(),active:form.elements.active.checked};
  try{const save=$('button[type="submit"]',form);save.disabled=true;save.textContent='Saving…';if(file)body.image_url=await uploadAdminImage(file);if(record)await sppApi(`/admin/team/${record.id}`,{method:'PUT',body:JSON.stringify(body)});else await sppApi('/admin/team',{method:'POST',body:JSON.stringify(body)});closeModal();toast('Team profile saved to MySQL and published.');await loadManagedPageData('team');}catch(err){toast(err.message||'Unable to save team profile.','warn');const save=$('button[type="submit"]',form);if(save){save.disabled=false;save.textContent=record?'Save changes':'Create & publish profile';}}
 });
}
function confirmDeleteTeam(id){const row=managedTeamRows.find(x=>Number(x.id)===Number(id));if(!row)return;if(!confirm(`Delete the team profile for ${row.name}? This also removes it from the public team page.`))return;sppApi(`/admin/team/${id}`,{method:'DELETE'}).then(()=>{toast('Team profile deleted.');loadManagedPageData('team');}).catch(e=>toast(e.message,'warn'));}
function news(){return `${header('Shoto News Publishing','Write, edit, schedule and publish articles directly to the public Shoto News website.',`<button class="btn primary" data-action="new-news-article">＋ New news article</button>`)}<section class="card section-card"><div class="card-head"><div><h3>Shoto News articles</h3><p>Published stories appear on news.html automatically. Drafts and review items stay private.</p></div><span class="status published" id="newsCount">Loading from database…</span></div><div class="toolbar"><input class="field" id="newsAdminSearch" placeholder="Search headlines…"><select class="select" id="newsStatusFilter"><option value="all">All statuses</option>${PUBLISHING_STATUSES.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="table-wrap"><table class="content-table"><thead><tr><th>Headline</th><th>Category</th><th>Status</th><th>Featured</th><th>Published</th><th>Actions</th></tr></thead><tbody id="newsArticleRows"><tr><td colspan="6"><div class="empty-state">Loading Shoto News records…</div></td></tr></tbody></table></div></section><section class="card section-card"><div class="card-head"><div><h3>Public newsroom</h3><p>Open the published website to verify live changes.</p></div><a class="btn" href="news.html" target="_blank" rel="noopener">Open Shoto News ↗</a></div><div class="section-body"><span class="helper-text">Publishing here sends approved content to the MySQL newsroom API. No HTML editing is required.</span></div></section>`;}
function renderManagedNewsRows(){
 const body=$('#newsArticleRows');if(!body)return;
 const filtered=managedNewsRows.filter(a=>{const q=($('#newsAdminSearch')?.value||'').toLowerCase(),st=$('#newsStatusFilter')?.value||'all';return (!q||`${a.title} ${a.category} ${a.author}`.toLowerCase().includes(q))&&(st==='all'||a.status===st);});
 const count=$('#newsCount');if(count)count.textContent=`${managedNewsRows.length} DATABASE RECORDS`;
 body.innerHTML=filtered.length?filtered.map(a=>`<tr><td><b>${escapeHtml(a.title)}</b><small style="display:block;color:#87949a">/${escapeHtml(a.slug)}</small></td><td>${escapeHtml(a.category)}</td><td><span class="status ${statusClassFor(a.status)}">${escapeHtml(a.status)}</span></td><td>${a.featured?'Yes':'No'}</td><td>${a.published_at?new Date(a.published_at).toLocaleString():'—'}</td><td><button class="btn" data-news-edit="${a.id}">Edit</button> <button class="btn danger" data-news-delete="${a.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="6"><div class="empty-state">No matching Shoto News articles. Create a new article to begin publishing.</div></td></tr>';
}
function openNewsEditor(record=null){
 const a=record||{},cats=[...new Set([...syfmNewsCategories.filter(x=>x!=='All headlines'),...(a.category?[a.category]:[])])];
 openModal(record?'Edit Shoto News article':'Create Shoto News article',`<form id="newsArticleForm" class="property-form"><label>Headline<input class="field" name="title" required value="${escapeAttr(a.title||'')}"></label><div class="cms-editor-meta"><label>URL slug<input class="field" name="slug" value="${escapeAttr(a.slug||'')}"></label><label>Category<select class="select" name="category">${cats.filter(x=>x!=='All headlines').map(x=>`<option value="${escapeAttr(x)}" ${a.category===x?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></label><label>Status<select class="select" name="status">${statusSelectOptions(a.status||'Draft')}</select></label><label>Author<input class="field" name="author" value="${escapeAttr(a.author||'')}" placeholder="Editorial desk"></label></div><label>Excerpt<textarea class="field" name="excerpt" rows="2">${escapeHtml(a.excerpt||'')}</textarea></label><label>Article body<textarea class="field" name="body" rows="9" required>${escapeHtml(a.body||'')}</textarea></label><label>Featured image URL<input class="field" name="imageUrl" id="newsImageUrl" value="${escapeAttr(a.image_url||'')}" placeholder="Upload an image or paste its URL"></label><label>Upload featured image<input class="field" type="file" id="newsImageFile" accept="image/*"></label><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" name="featured" ${a.featured?'checked':''}> Feature this article on the Shoto News page</label><label>Scheduled publication date (for Scheduled status)<input class="field" name="scheduledAt" type="datetime-local" value="${a.scheduled_at?new Date(a.scheduled_at).toISOString().slice(0,16):''}"></label><div style="display:flex;justify-content:flex-end;gap:8px"><button class="btn" type="button" id="newsCancel">Cancel</button><button class="btn primary" type="submit">${record?'Save article':'Save & publish article'}</button></div></form>`,'SHOTO NEWS EDITOR');
 $('#newsCancel').addEventListener('click',closeModal);
 $('#newsArticleForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form);const file=$('#newsImageFile').files[0],btn=$('button[type="submit"]',form);const body={title:String(fd.get('title')||'').trim(),slug:String(fd.get('slug')||'').trim(),category:fd.get('category'),status:fd.get('status'),author:fd.get('author'),excerpt:fd.get('excerpt'),body:fd.get('body'),imageUrl:$('#newsImageUrl').value.trim(),featured:form.elements.featured.checked,scheduledAt:fd.get('scheduledAt')?`${fd.get('scheduledAt').replace('T',' ')}:00`:null};try{btn.disabled=true;btn.textContent='Saving…';if(file)body.imageUrl=await uploadAdminImage(file);if(record)await sppApi(`/admin/news/articles/${record.id}`,{method:'PUT',body:JSON.stringify(body)});else await sppApi('/admin/news/articles',{method:'POST',body:JSON.stringify(body)});closeModal();toast('Shoto News article saved to MySQL. Published items are now public.');await loadManagedPageData('news');}catch(err){toast(err.message||'Unable to save Shoto News article.','warn');btn.disabled=false;btn.textContent=record?'Save article':'Save & publish article';}});
}
function confirmDeleteNews(id){const row=managedNewsRows.find(x=>Number(x.id)===Number(id));if(!row)return;if(!confirm(`Delete the news article “${row.title}”?`))return;sppApi(`/admin/news/articles/${id}`,{method:'DELETE'}).then(()=>{toast('News article deleted.');loadManagedPageData('news');}).catch(e=>toast(e.message,'warn'));}
async function saveSyfmNavigation(){
 const rows=$$('#syfmNavigationRows [data-syfm-row]').map(row=>({label:row.querySelector('[data-syfm-label]')?.value.trim()||'',href:row.querySelector('[data-syfm-href]')?.value.trim()||'#home',enabled:!!row.querySelector('[data-syfm-enabled]')?.checked})).filter(x=>x.label);
 const categories=String($('#syfmCategories')?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 const joinUrl=String($('#syfmJoinUrl')?.value||'MemberShip.html').trim();
 try{const result=await sppApi('/admin/syfm/navigation',{method:'PUT',body:JSON.stringify({navigation:rows,newsCategories:categories,joinUrl})});syfmSettings={...syfmSettings,...(result.data||{navigation:rows,newsCategories:categories,joinUrl})};syfmMenuItems=rows.map(x=>x.label);syfmNewsCategories=categories;toast('SYFM navigation and categories published to the public website.');setPage('syfm');}catch(e){toast(e.message||'Could not publish SYFM navigation.','warn');}
}
