function analytics(){return `${header('Analytics & Reports','Explore website, content, video, audience and revenue performance.',`<select class="select" id="analyticsRange"><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option><option value="12m">Last 12 months</option><option value="24h">Last 24 hours</option></select><button class="btn" data-action="export-report">⇩ Export CSV</button>`)}${demoNote('All figures are illustrative. Connect analytics providers and event tracking to calculate real performance.')}<div class="grid four-col">${[['Unique visitors','32,108'],['Page views','126,840'],['Video watch time','1,348 hrs'],['Engagement rate','68.4%']].map(x=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><small>Selected period · Demo data</small></div>`).join('')}</div><section class="card section-card" style="margin-top:15px"><div class="card-head"><div><h3>Traffic & engagement trends</h3><p>Use the period selector to change the sample series.</p></div><span class="status">Interactive range</span></div><div class="chart-legend"><span><i class="legend-dot" style="background:#4c8cf5"></i>Visitors</span><span><i class="legend-dot" style="background:#76d94e"></i>Page views</span><span><i class="legend-dot" style="background:#bd8aef"></i>Engagement</span></div><div class="chart-wrap" id="analyticsChart">${lineChart('7d')}</div></section><div class="grid three-col"><section class="card mini-stat"><h3>Content category share</h3><div class="donut-row"><div class="donut"></div><div class="donut-legend"><div><span>Video</span><b>43%</b></div><div><span>Articles</span><b>27%</b></div><div><span>Images</span><b>19%</b></div><div><span>Other</span><b>11%</b></div></div></div></section><section class="card mini-stat"><h3>Top content</h3><div class="quick-row"><span>Production Showreel</span><b>24.8K</b></div><div class="quick-row"><span>Behind the Lens</span><b>18.4K</b></div><div class="quick-row"><span>Studio Stories</span><b>12.1K</b></div></section><section class="card mini-stat"><h3>Audience snapshot</h3><div class="quick-row"><span>Mobile audience</span><b>58.6%</b></div><div class="quick-row"><span>Returning visitors</span><b>34.2%</b></div><div class="quick-row"><span>Average session</span><b>03:42</b></div></section></div>`;}
function payments(){return `${header('Payments & Revenue','Review payment activity, orders, transaction status and commercial performance.',`<button class="btn" data-action="export-report">⇩ Export transactions</button>`)}${demoNote('No payment gateway is connected. These are fictional transaction examples; do not use them as financial records.')}<div class="grid four-col">${[['Revenue this month','₦850,000'],['Successful payments','126'],['Pending settlement','₦74,500'],['Refunds','₦12,000']].map(x=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><small>Illustrative financial data</small></div>`).join('')}</div><section class="card section-card" style="margin-top:15px"><div class="card-head"><h3>Recent transactions</h3><span class="status">Demo ledger</span></div><div class="table-wrap"><table class="content-table"><thead><tr><th>Reference</th><th>Customer</th><th>Purpose</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead><tbody><tr><td>SPP-DEMO-001</td><td>Customer A</td><td>Production deposit</td><td>₦250,000</td><td>Oct 30</td><td><span class="status published">Paid</span></td></tr><tr><td>SPP-DEMO-002</td><td>Customer B</td><td>Event ticket</td><td>₦15,000</td><td>Oct 29</td><td><span class="status pending">Pending</span></td></tr><tr><td>SPP-DEMO-003</td><td>Customer C</td><td>Media services</td><td>₦85,000</td><td>Oct 28</td><td><span class="status published">Paid</span></td></tr></tbody></table></div></section>`;}
function schedule(){let cells='';for(let i=1;i<=35;i++){const n=i<=31?i:'';const ev=n==='4'?'Article · 10:00':n==='12'?'Showreel · 16:30':n==='21'?'Creator event':'';cells+=`<div class="day"><b>${n}</b>${ev?`<span class="event-dot">${ev}</span>`:''}</div>`;}return `${header('Scheduled Publishing','Plan and review upcoming content releases and promotional activity.',`<button class="btn primary" data-action="new-schedule">＋ Schedule content</button>`)}${demoNote('Calendar items are sample entries and are not queued with an external publishing service.')}<section class="card"><div class="card-head"><div><h3>November 2026</h3><p>Publishing calendar · Editorial and media schedule</p></div><div><button class="btn">‹</button> <button class="btn">›</button></div></div><div class="calendar">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d=>`<div class="day" style="min-height:auto;border:0;background:none;color:#c4cdd1;font-weight:700">${d}</div>`).join('')}${cells}</div></section>`;}
