function ai(){const tabs=['Image','Video','Audio','Script','Design','Presentation','Post-production'];return `${header('SPP AI Creative Studio','A multi-provider creative workspace for writing, image-making, video, voice, design and production hand-off.',`<span class="status pending">PROVIDER SETUP REQUIRED</span>`)}${demoNote('This screen demonstrates the workflow only. AI generations are not sent to vendors and no provider accounts or API keys are connected.')}<section class="ai-hero"><div><div class="eyebrow">CREATIVE INTELLIGENCE / MULTI-MODEL WORKSPACE</div><h2>Make the next story remarkable.</h2><p>Bring creative briefs, scripts, visuals, voice and video workflows into one production desk. Choose a provider, prepare a brief, review the result and send approved assets into the SPP Media Library.</p><div style="display:flex;gap:8px;margin-top:15px"><button class="btn primary" data-action="new-ai-project">＋ New creative project</button><button class="btn" data-action="ai-history">Generation history</button></div></div><div class="ai-orb">✦</div></section><div class="grid two-col"><section class="card"><div class="card-head"><h3>Creative workspace</h3><span class="status">Local demo</span></div><div class="section-body"><div class="toolbar-left" style="margin-bottom:13px"><div class="integration-filters">${tabs.map(t=>`<button class="chip ${activeStudioTab===t?'active':''}" data-ai-tab="${t}">${t}</button>`).join('')}</div></div><label style="display:block;font-size:10px;color:#98a5ab;margin-bottom:7px">AI provider</label><select class="select" id="providerSelect" style="width:100%;margin-bottom:12px">${providers.map(p=>`<option ${p===selectedProvider?'selected':''}>${p}</option>`).join('')}</select><label style="display:block;font-size:10px;color:#98a5ab;margin-bottom:7px">Creative brief / prompt</label><textarea class="prompt-area" id="aiPrompt" placeholder="Describe the asset or creative work you want to produce...">Create a cinematic promotional concept for Shoto Point Production. Visual direction: premium black and gold, film production atmosphere, confident storytelling.</textarea><div class="form-grid" style="margin-top:11px"><label>Aspect ratio<select class="select"><option>16:9 Landscape</option><option>9:16 Portrait</option><option>1:1 Square</option><option>4:5 Social portrait</option></select></label><label>Output style<select class="select"><option>Cinematic / Premium</option><option>Documentary</option><option>Editorial</option><option>Minimal</option></select></label></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;gap:10px"><small style="color:#77848b">Provider costs and limits are not active in demo mode.</small><button class="btn primary" data-action="generate-demo">✦ Generate demo job</button></div></div></section><section class="card"><div class="card-head"><h3>Studio output</h3><span class="status">Preview panel</span></div><div class="section-body"><div class="output-preview" id="aiOutput"><div><div style="font-size:28px;color:#00d96b">✧</div><strong style="display:block;color:#c5cfd3;font-size:11px;margin:8px">Your creative output will appear here</strong><small>Run a demo job to preview the workflow and job tracking.</small></div></div><div id="aiJobList" style="margin-top:13px">${generatedJobs.slice(0,3).map(job=>`<div class="quick-row"><span>${escapeHtml(job.name)}</span><span class="status pending">Demo queued</span></div>`).join('')}</div></div></section></div><section class="card section-card" style="margin-top:15px"><div class="card-head"><div><h3>Connected creative ecosystem</h3><p>Provider catalogue · setup is required for actual generation</p></div><button class="btn" data-page="integrations">Open integration centre ↗</button></div><div class="provider-grid" style="padding:14px">${providers.slice(0,16).map(p=>`<div class="provider-card"><div class="provider-logo">${p.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div style="min-width:0"><strong>${p}</strong><small>Configure credentials to connect</small></div><span class="provider-status">○</span></div>`).join('')}</div></section>`;}
function integrations(){const filtered=integrationData.filter(p=>(selectedIntegrationCategory==='All'||p.category===selectedIntegrationCategory)&&(p.name+' '+p.description+' '+p.category).toLowerCase().includes(integrationSearch.toLowerCase()));const cats=['All',...new Set(integrationData.map(p=>p.category))];return `${header('Plugins & Integrations','One administration centre for AI providers, website extensions, analytics, payments, communications and infrastructure.',`<span class="status pending">${integrationData.length} CATALOGUE ITEMS</span>`)}${demoNote('The catalogue contains planned integration options. None is authenticated by this prototype. “Configure” opens a setup brief; it does not connect a vendor.')}<div class="grid four-col" style="margin-bottom:15px">${[['Catalogue items','100'],['Connected','0'],['Setup required','100'],['Connection errors','0']].map((x,i)=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><small>${i===0?'Planned catalogue': 'Current prototype state'}</small></div>`).join('')}</div><section class="card"><div class="toolbar"><div class="toolbar-left"><input id="integrationSearch" placeholder="Search 100 integrations..." value="${escapeAttr(integrationSearch)}"/><span class="status">${filtered.length} results</span></div><div class="toolbar-right"><button class="btn" data-action="integration-audit">Integration audit</button></div></div><div class="toolbar" style="border-top:0"><div class="integration-filters">${cats.map(c=>`<button class="chip ${selectedIntegrationCategory===c?'active':''}" data-integration-cat="${escapeAttr(c)}">${c}</button>`).join('')}</div></div><div class="integration-grid" id="integrationGrid">${filtered.map(p=>{const override=pluginOverrides[p.id];const status=override==='connected'?'Connected':p.category==='AI & Creative'?'Setup required':'Available';return `<article class="integration-card"><div class="integration-top"><div class="integration-logo">${escapeHtml(p.logo)}</div><div style="min-width:0;flex:1"><strong>${escapeHtml(p.id+'. '+p.name)}</strong><small>${escapeHtml(p.category)}</small></div></div><p>${escapeHtml(p.description)}</p><div class="integration-bottom"><span class="status ${status==='Connected'?'connected':status==='Setup required'?'setup':''}">${status}</span><button class="btn" data-integration-id="${p.id}">Configure</button></div></article>`;}).join('')}</div></section>`;}
function developer(){return `${header('Developer Studio','Inspect and edit frontend snippets, manage project files and prepare integration code.',`<button class="btn" data-action="format-code">Format</button><button class="btn primary" data-action="save-code">Save snippet</button>`)}${demoNote('The editor below is a local textarea demonstration, not a live filesystem or deployment editor.')}<div class="grid two-col"><section class="card"><div class="card-head"><h3>Code workspace</h3><span class="status">HTML / CSS / JS</span></div><div class="section-body"><div class="integration-filters" style="margin-bottom:10px"><button class="chip active" data-code-tab="HTML">HTML</button><button class="chip" data-code-tab="CSS">CSS</button><button class="chip" data-code-tab="JavaScript">JavaScript</button><button class="chip" data-code-tab="JSON">JSON</button></div><textarea class="editor" id="codeEditor">&lt;section class="spp-feature"&gt;\n  &lt;h1&gt;Stories that move people&lt;/h1&gt;\n  &lt;p&gt;Film · Television · Storytelling&lt;/p&gt;\n&lt;/section&gt;</textarea></div></section><section class="card"><div class="card-head"><h3>Project environment</h3></div><div class="section-body"><div class="quick-row"><span>Application</span><b>SPP Operations Centre</b></div><div class="quick-row"><span>Frontend mode</span><b>Standalone prototype</b></div><div class="quick-row"><span>Backend connection</span><span class="status pending">Not configured</span></div><div class="quick-row"><span>Deployment target</span><b>Not configured</b></div><p style="color:#829097;font-size:10px;line-height:1.6;margin-top:15px">Connect your source repository and deployment environment before using production code editing or release controls.</p></div></section></div>`;}
function videoedit(){return `${header('Video Editing Workspace','A production timeline concept for organising footage, audio, titles and post-production hand-off.',`<button class="btn" data-action="new-edit-project">New project</button><button class="btn primary" data-action="export-timeline">Export hand-off</button>`)}${demoNote('This is a timeline interface prototype. It does not decode, render or edit full-resolution footage. Use CapCut or DaVinci Resolve hand-off for actual editing.')}<div class="grid two-col"><section class="card"><div class="card-head"><h3>Preview monitor</h3><span class="status">Preview only</span></div><div style="margin:15px;background:#050708;border-radius:8px;aspect-ratio:16/9;display:grid;place-items:center;color:#87959d;overflow:hidden"><div style="text-align:center"><div style="font-size:38px;color:#00d96b">▶</div><strong style="font-size:11px">SPP production timeline</strong><p style="font-size:9px">Import media to prepare an edit hand-off.</p></div></div><div class="toolbar" style="border:0"><span style="font-size:10px;color:#a4afb4">00:00:15:24 / 00:03:45:18</span><button class="btn">▶ Play preview</button></div></section><section class="card"><div class="card-head"><h3>Inspector</h3></div><div class="property-form"><label>Selected clip<input class="field" value="Interview_Sequence_01.mp4"/></label><label>Scale<input type="range" min="50" max="150" value="100"/></label><label>Opacity<input type="range" min="0" max="100" value="100"/></label><label>Rotation<input type="number" value="0"/></label><button class="btn" data-action="handoff-edit">Prepare editor hand-off</button></div></section></div><section class="card section-card" style="margin-top:15px"><div class="card-head"><h3>Timeline tracks</h3><span class="status">Sample sequence</span></div><div class="timeline"><div class="track"><label>VIDEO 01</label><div class="track-bar">Footage sequence · 00:00–01:30</div></div><div class="track"><label>TITLES</label><div class="track-bar">Opening title / lower thirds</div></div><div class="track"><label>AUDIO</label><div class="track-bar">Narration and soundtrack</div></div></div></section>`;}
function settings(){return `${header('System & Security','Monitor application configuration, administrator permissions, audit activity and infrastructure.',`<button class="btn primary" data-action="save-settings">Save settings</button>`)}${demoNote('Resource levels and service checks are mock monitoring indicators; connect server monitoring for live telemetry.')}<div class="grid three-col">${[['CPU usage','28%'],['Memory usage','62%'],['Media storage','71%']].map((x,i)=>`<div class="card stat-card"><span class="stat-label">${x[0]}</span><strong>${x[1]}</strong><div class="progress"><i style="width:${x[1]};background:${i===1?'#00d96b':i===2?'#76d94e':'#4c8cf5'}"></i></div><small>Demo resource meter</small></div>`).join('')}</div><div class="grid two-col" style="margin-top:15px"><section class="card"><div class="card-head"><h3>Security configuration</h3></div><div class="section-body"><div class="quick-row"><span>Administrator MFA</span><span class="status pending">Not configured</span></div><div class="quick-row"><span>API secrets storage</span><span class="status pending">Backend required</span></div><div class="quick-row"><span>Role-based permissions</span><span class="status">Design required</span></div><div class="quick-row"><span>Audit trail</span><span class="status">Demo events only</span></div></div></section><section class="card"><div class="card-head"><h3>System activity log</h3><button class="btn" data-action="export-report">Export</button></div><div class="activity-list"><div class="activity-item"><i class="activity-bullet"></i><div><strong>Admin session opened</strong><small>Local demo session · Just now</small></div></div><div class="activity-item"><i class="activity-bullet"></i><div><strong>Workspace modules loaded</strong><small>Prototype frontend · Current session</small></div></div><div class="activity-item"><i class="activity-bullet"></i><div><strong>No external integrations authenticated</strong><small>Configuration required</small></div></div></div></section></div>`;}
function renderPage(page){return ({overview,website,cms,menus,news,seo,media,videos,production,syfm,team,events,community,analytics,payments,schedule,ai,integrations,developer,videoedit,settings})[page]();}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function escapeAttr(s){return escapeHtml(s).replace(/`/g,'&#96;');}
function openModal(title,body,eyebrow='DETAILS'){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalEyebrow').textContent=eyebrow;$('#modalBackdrop').hidden=false;}
function closeModal(){$('#modalBackdrop').hidden=true;}
function bindPageInteractions(){
  $$('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
  const or=$('#overviewRange');if(or)or.addEventListener('change',()=>$('#overviewChart').innerHTML=lineChart(or.value));
  const ar=$('#analyticsRange');if(ar)ar.addEventListener('change',()=>$('#analyticsChart').innerHTML=lineChart(ar.value));
  const title=$('#propTitle'),body=$('#propBody'),button=$('#propButton');[title,body,button].filter(Boolean).forEach(el=>el.addEventListener('input',()=>{const s=builderSections.find(x=>x.id===selectedSection);if(!s)return;if(el===title){s.title=el.value;s.titleHtml='';}else if(el===body)s.body=el.value;else s.button=el.value;store.set('builderSections',builderSections);}));
  const propAlign=$('#propAlign'),propUrl=$('#propUrl'),propMediaUrl=$('#propMediaUrl');[propAlign,propUrl,propMediaUrl].filter(Boolean).forEach(el=>el.addEventListener('change',()=>{const s=builderSections.find(x=>x.id===selectedSection);if(!s)return;if(el===propAlign)s.align=el.value;else if(el===propUrl)s.url=el.value;else s.mediaUrl=el.value;store.set('builderSections',builderSections);if(el===propAlign)setPage('website');}));
  const socialLinks=$('#propSocialLinks');if(socialLinks)socialLinks.addEventListener('input',()=>{const sec=builderSections.find(x=>x.id===selectedSection);if(sec){sec.socialLinksText=socialLinks.value;store.set('builderSections',builderSections);}});
  const builderFont=$('#builderFont'),builderSize=$('#builderFontSize');if(builderFont)builderFont.addEventListener('change',e=>{document.execCommand('fontName',false,e.target.value);});if(builderSize)builderSize.addEventListener('change',e=>{document.execCommand('fontSize',false,e.target.value);});
  const cmsSearch=$('#cmsSearch'),cmsFilter=$('#cmsTypeFilter'),cmsStatus=$('#cmsStatusFilter');if(cmsSearch)cmsSearch.addEventListener('input',()=>filterCmsRows());if(cmsFilter)cmsFilter.addEventListener('change',()=>filterCmsRows());if(cmsStatus)cmsStatus.addEventListener('change',()=>filterCmsRows());
  const ms=$('#mediaSearch');if(ms)ms.addEventListener('input',()=>filterMedia(ms.value));
  const mf=$('#mediaFilter');if(mf)mf.addEventListener('change',()=>{selectedMediaFilter=mf.value;setPage('media');});
  const is=$('#integrationSearch');if(is)is.addEventListener('input',()=>{integrationSearch=is.value;const pos=is.selectionStart;const oldPage=currentPage;$('#content').innerHTML=integrations();bindPageInteractions();const ni=$('#integrationSearch');ni.focus();ni.setSelectionRange(pos,pos);});
  const ps=$('#providerSelect');if(ps)ps.addEventListener('change',()=>selectedProvider=ps.value);
  const st=$('#seoTitle'),sd=$('#seoDescription');[st,sd].filter(Boolean).forEach(el=>el.addEventListener('input',()=>{if(st)$('#seoPreviewTitle').textContent=st.value;if(sd)$('#seoPreviewDesc').textContent=sd.value;}));
  const radio=$('#radioToggle');if(radio)radio.addEventListener('click',()=>{radio.textContent=radio.textContent.includes('Play')?'Ⅱ Pause preview':'▷ Play preview';toast('Demo radio preview control toggled. No live stream is connected.','warn');});
}
function filterCmsRows(){const q=($('#cmsSearch')?.value||'').toLowerCase(),t=$('#cmsTypeFilter')?.value||'All content types',st=$('#cmsStatusFilter')?.value||'All statuses';$$('#cmsRows tr').forEach(row=>{const text=row.textContent.toLowerCase();const matchType=t==='All content types'||row.children[1]?.textContent===t;const matchStatus=st==='All statuses'||row.children[5]?.textContent.trim()===st;row.style.display=text.includes(q)&&matchType&&matchStatus?'':'none';});}
function updatePost(postId,fn){const state=postEngagement[postId]||{likes:12,reactions:4,shares:2,comments:3,liked:false};fn(state);postEngagement[postId]=state;store.set('postEngagement',postEngagement);const card=$(`[data-post-card="${CSS.escape(postId)}"]`);if(card){const parent=card.parentElement;const old=card.outerHTML;const fresh=document.createElement('div');fresh.innerHTML=renderEngagementPost(postId,card.querySelector('.post-card-body strong')?.textContent||'SPP story');card.replaceWith(fresh.firstElementChild);}}

function filterMedia(q){const cards=$$('.media-card',$('#mediaGrid'));cards.forEach(c=>c.style.display=c.dataset.mediaName.toLowerCase().includes(q.toLowerCase())?'':'none');}
function saveBuilder(){store.set('builderSections',builderSections);toast('Page draft saved in this browser.');}
function showMedia(item){const media=item.type==='video'?`<video controls autoplay src="${item.src}" poster="${item.poster||''}" style="width:100%"></video>`:item.type==='audio'?`<audio controls autoplay src="${item.src}" style="width:100%"></audio>`:item.type==='document'?`<div class="document-preview">▤ <a href="${escapeAttr(item.src||'#')}" target="_blank" rel="noopener">${escapeHtml(item.name)}</a><span>Document file</span></div>`:`<img src="${item.src}" alt="${escapeAttr(item.name)}"/>`;openModal(item.name,`${media}<div style="display:flex;justify-content:space-between;gap:10px;margin-top:15px;flex-wrap:wrap"><div><strong style="font-size:11px">${escapeHtml(item.category||'Uploaded asset')}</strong><p style="color:#89969c;font-size:10px">${item.type.toUpperCase()} · ${item.size||'Local preview'} · ${item.views||'Not yet measured'}</p></div><button class="btn" id="mediaFeature">☆ Set as featured</button></div>`,'MEDIA PREVIEW');$('#mediaFeature').addEventListener('click',()=>toast('Featured selection stored for this demo session.'));
}
function showIntegration(id){const p=integrationData.find(x=>x.id===Number(id));if(!p)return;openModal(`Configure ${p.name}`,`<div class="demo-note"><strong>SETUP REQUIRED</strong><span>This is a setup guide. No live authentication will occur in this prototype.</span></div><p style="font-size:11px;color:#b7c2c7;line-height:1.6">${escapeHtml(p.description)}.</p><div class="form-grid"><label class="full">Integration name<input class="field" value="${escapeAttr(p.name)}" disabled></label><label>Connection method<select class="select"><option>OAuth 2.0 (where supported)</option><option>Server-side API key</option><option>Webhook</option><option>Project hand-off / export</option><option>WordPress plugin</option></select></label><label>Environment<select class="select"><option>Sandbox / test</option><option>Production</option></select></label><label class="full">API endpoint / account reference<input class="field" placeholder="Enter provider endpoint or account identifier"></label><label class="full">Notes<textarea placeholder="Required scopes, webhook URL, account owner and setup notes"></textarea></label></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px"><button class="btn" id="integrationMarkAvailable">Mark for setup</button><button class="btn primary" id="integrationSave">Save configuration note</button></div>`,'INTEGRATION SETUP');$('#integrationMarkAvailable').addEventListener('click',()=>{pluginOverrides[p.id]='setup';store.set('pluginOverrides',pluginOverrides);closeModal();setPage('integrations');toast(`${p.name} marked for setup.`,'warn');});$('#integrationSave').addEventListener('click',()=>{toast('Configuration note saved to the local demo session.','warn');closeModal();});}
function addSection(type){
 const defaults={
  header:['Website header','Logo, navigation and call-to-action links.'],hero:['New hero section','Add a compelling headline and supporting message.'],text:['New text section','Write and format your content here.'],image:['Image block','Attach an image and write alternative text.'],video:['Video block','Attach video media with a poster and controls.'],audio:['Audio block','Attach narration, music or programme audio.'],section:['New section','Reusable section for page content.'],page:['New page','A new page-level content area.'],cards:['New content cards','Add a short introduction to your cards.'],columns:['Column layout','Add content into a multi-column layout.'],rows:['Row layout','Arrange content in horizontal rows.'],gallery:['Image gallery','Select images from the media library.'],news:['Latest news','Display recent newsroom stories with comments and reactions.'],blog:['Blog feed','Display blog posts and reader interactions.'],articles:['Article feed','Display published articles and engagement controls.'],document:['Document download','Attach a document or production brief.'],social:['Social media links','Add social profile icons and destination URLs.'],link:['URL link','Add a button or link to another page.'],comments:['Comments panel','Allow discussion under each post.'],reactions:['Post reactions','Enable likes, reactions and shares.'],team:['Meet the team','Show team profiles and roles.'],footer:['Website footer','Contact details · Social links · Copyright']};
 const d=defaults[type]||defaults.text;const s={id:Date.now()+Math.floor(Math.random()*1000),type,title:d[0],body:d[1],button:'Explore',align:'centre',url:'',mediaUrl:'',mediaType:''};builderSections.push(s);selectedSection=s.id;store.set('builderSections',builderSections);setPage('website');toast(`${type} block added to the page.`);
}

function handlePostAction(el){
 const id=el.dataset.postId;const action=el.dataset.postAction;const state=postEngagement[id]||{likes:12,reactions:4,shares:2,comments:3,liked:false};
 if(action==='like'){state.liked=!state.liked;state.likes=Math.max(0,state.likes+(state.liked?1:-1));}
 else if(action==='react'){const menu=el.closest('.post-card-body')?.querySelector('.reaction-picks');if(menu)menu.classList.toggle('open');return;}
 else if(action.startsWith('reaction-')){state.reactions=(state.reactions||0)+1;state.lastReaction=action.replace('reaction-','');toast(`Reaction added: ${state.lastReaction}.`);}
 else if(action==='toggle-comments'){const box=$(`#comments-${CSS.escape(id)}`);if(box)box.hidden=!box.hidden;return;}
 else if(action==='submit-comment'){const input=$(`[data-comment-input="${CSS.escape(id)}"]`);if(!input||!input.value.trim()){toast('Write a comment first.','warn');return;}state.comments=(state.comments||0)+1;input.value='';toast('Comment added to the local demo post.');}
 else if(action==='share'){state.shares=(state.shares||0)+1;toast('Demo share count updated. Public sharing requires a live post URL.','warn');}
 postEngagement[id]=state;store.set('postEngagement',postEngagement);
 const card=el.closest('.post-card');if(card){const title=card.querySelector('.post-card-body strong')?.textContent||'SPP story';const tmp=document.createElement('div');tmp.innerHTML=renderEngagementPost(id,title);card.replaceWith(tmp.firstElementChild);}
}

function handleAction(action,el){
 switch(action){
 case 'builder-preview':openModal('Website preview',`<div style="background:#eee;color:#151515;padding:20px;border-radius:9px"><h1 style="font:700 24px 'Space Grotesk'">Shoto Point Production</h1><p>Preview mode is using your locally saved page sections.</p>${builderSections.map(s=>`<h2>${escapeHtml(s.title)}</h2><p>${escapeHtml(s.body)}</p>`).join('')}</div>`,'PREVIEW');break;
 case 'builder-save':saveBuilder();break;
 case 'builder-publish':openModal('Publish website page',`<div class="demo-note"><strong>BACKEND REQUIRED</strong><span>This prototype cannot publish to your live website.</span></div><p style="font-size:11px;line-height:1.6;color:#aeb9be">Your draft can be prepared here. To publish for real, connect the website/CMS API, validate permissions, and configure a deployment or publishing endpoint.</p><button class="btn primary" id="publishSave">Save draft locally</button>`,'PUBLISH WORKFLOW');$('#publishSave').addEventListener('click',()=>{saveBuilder();closeModal();});break;
 case 'move-section':{const idx=builderSections.findIndex(s=>s.id===selectedSection),dir=el.dataset.dir,n=dir==='up'?idx-1:idx+1;if(n>=0&&n<builderSections.length){[builderSections[idx],builderSections[n]]=[builderSections[n],builderSections[idx]];store.set('builderSections',builderSections);setPage('website');}break;}
 case 'delete-section':builderSections=builderSections.filter(s=>s.id!==selectedSection);selectedSection=builderSections[0]?.id||null;store.set('builderSections',builderSections);setPage('website');toast('Section removed.');break;
 case 'upload-media':$('#mediaUpload').click();break;
 case 'new-folder':openModal('Create media folder',`<label style="display:grid;gap:7px;color:#9aa5aa;font-size:10px">Folder name<input class="field" id="folderName" placeholder="e.g. Campaign Photography"/></label><button class="btn primary" style="margin-top:14px" id="makeFolder">Create folder</button>`);$('#makeFolder').addEventListener('click',()=>{const v=$('#folderName').value.trim();if(v){closeModal();toast(`Folder “${v}” created in the demo workspace.`);}else toast('Enter a folder name.','warn');});break;
 case 'new-team':openTeamEditor();break;
 case 'new-news-article':openNewsEditor();break;
 case 'new-submission':case 'new-programme':case 'new-project':case 'new-event':case 'new-playlist':case 'new-schedule':case 'invite-creator':case 'new-edit-project':case 'new-ai-project':openCreateForm(action);break;
 case 'edit-content':openCmsEditor();break;
 case 'new-article':openCmsEditor('Article');break;
 case 'syfm-add-menu':{const label=prompt('New SYFM navigation label');if(label&&label.trim()){syfmSettings.navigation.push({label:label.trim(),href:'#home',enabled:true});renderSyfmEditor();}break;}
 case 'syfm-reset-menu':syfmSettings.navigation=[{label:'Home',href:'#home',enabled:true},{label:'About',href:'#about',enabled:true},{label:'Vision',href:'#vision',enabled:true},{label:'Programmes',href:'#programmes',enabled:true},{label:'Leadership',href:'#leadership',enabled:true},{label:'Public Affairs',href:'#public-affairs',enabled:true},{label:'Membership',href:'#membership',enabled:true},{label:'Events',href:'#events',enabled:true},{label:'News',href:'#news',enabled:true},{label:'Gallery',href:'#gallery',enabled:true},{label:'Contact',href:'#contact',enabled:true}];renderSyfmEditor();toast('Default SYFM menu restored. Save & publish to make it live.');break;
 case 'syfm-save':saveSyfmNavigation();break;
 case 'syfm-join':$('#syfmJoinUrl')?.focus();toast('Edit JOIN SYFM destination above, then Save & publish SYFM.');break;
 case 'builder-attach-media':mediaUploadContext='builder';$('#mediaUpload').accept='image/*,video/*,audio/*,.pdf,.doc,.docx,.ppt,.pptx';$('#mediaUpload').click();break;
 case 'builder-insert-social':addSection('social');break;
 case 'review-submission':openModal('Review community submission',`<h3>Community Film Showcase Announced</h3><p style="color:#a0abb0;font-size:10px;line-height:1.6">Review contributor details, check media rights and verify editorial standards before approval.</p><div style="display:flex;gap:8px;margin-top:16px"><button class="btn primary" id="approveSubmission">Approve (demo)</button><button class="btn danger" id="rejectSubmission">Request changes</button></div>`,'EDITORIAL MODERATION');$('#approveSubmission').addEventListener('click',()=>{closeModal();toast('Submission marked approved in the demo workflow.');});$('#rejectSubmission').addEventListener('click',()=>{closeModal();toast('Change request recorded in demo workflow.','warn');});break;
 case 'seo-save':toast('SEO settings saved in the demo browser session.');break;
 case 'manage-featured':openModal('Featured video placement',`<label style="display:grid;gap:7px;font-size:10px;color:#9da8ad">Featured video<select class="select"><option>Shoto Point Showreel 2026</option><option>The Making of a Story</option><option>Behind the Lens</option></select></label><label style="display:flex;gap:8px;align-items:center;margin-top:13px;font-size:10px"><input type="checkbox" checked/> Display on homepage</label><button class="btn primary" style="margin-top:14px" id="saveFeatured">Save placement</button>`);$('#saveFeatured').addEventListener('click',()=>{closeModal();toast('Featured placement updated locally.');});break;
 case 'generate-demo':{const prompt=$('#aiPrompt')?.value.trim();if(!prompt){toast('Enter a creative brief first.','warn');break;}const job={name:`${activeStudioTab} job · ${new Date().toLocaleTimeString()}`,provider:selectedProvider,prompt,created:new Date().toISOString()};generatedJobs.unshift(job);generatedJobs=generatedJobs.slice(0,10);store.set('generatedJobs',generatedJobs);$('#aiOutput').innerHTML=`<div><div style="font-size:30px;color:#00d96b">✦</div><strong style="display:block;color:#f0d36e;font-size:12px;margin:8px">Demo job created</strong><small>${escapeHtml(selectedProvider)} · ${activeStudioTab}</small><p style="font-size:10px;color:#9aa6ac;line-height:1.6">${escapeHtml(prompt.slice(0,220))}</p><span class="status pending">Not sent to provider</span></div>`;$('#aiJobList').innerHTML=generatedJobs.slice(0,3).map(j=>`<div class="quick-row"><span>${escapeHtml(j.name)}</span><span class="status pending">Demo queued</span></div>`).join('');toast('Demo creative job added. No external AI request was made.','warn');break;}
 case 'ai-history':openModal('Creative generation history',generatedJobs.length?generatedJobs.map(j=>`<div class="activity-item"><i class="activity-bullet"></i><div><strong>${escapeHtml(j.name)}</strong><small>${escapeHtml(j.provider)} · ${new Date(j.created).toLocaleString()}</small><p style="font-size:9px;color:#86939a">${escapeHtml(j.prompt.slice(0,180))}</p></div></div>`).join(''):'<div class="empty-state">No creative jobs in this browser session.</div>','AI JOB HISTORY');break;
 case 'integration-audit':openModal('Integration readiness audit',`<div class="quick-row"><span>Catalogue records</span><b>100</b></div><div class="quick-row"><span>Provider credentials stored</span><b>0</b></div><div class="quick-row"><span>Verified connections</span><b>0</b></div><div class="quick-row"><span>Webhook endpoints</span><b>0</b></div><p style="font-size:10px;color:#8d999f;line-height:1.6;margin-top:12px">Before production, implement encrypted secret management, OAuth consent, scope restrictions, webhook signature verification, retries, audit logs and vendor-specific health checks.</p>`,'INTEGRATION AUDIT');break;
 case 'export-report':exportCsv();break;
 case 'menu-add':{const v=$('#newMenuItem').value.trim();if(v){currentMenuItems.push(v);store.set('primaryMenuItems',currentMenuItems);setPage('menus');toast('Navigation item added.');}else toast('Enter a menu label.','warn');break;}
 case 'menu-save':store.set('primaryMenuItems',currentMenuItems);store.set('primarySubmenus',siteNavSubmenus);toast('Primary Shoto navigation remains browser-only; SYFM navigation is database-published.','warn');break;
 case 'menu-reset':currentMenuItems=[...primaryMenuDefaults];siteNavSubmenus=JSON.parse(JSON.stringify(primarySubmenuDefaults));store.set('primaryMenuItems',currentMenuItems);store.set('primarySubmenus',siteNavSubmenus);setPage('menus');toast('Requested primary menu restored.');break;
 case 'format-code':{const e=$('#codeEditor');if(e)e.value=e.value.split('\n').map(l=>l.trimEnd()).join('\n');toast('Basic whitespace cleanup applied.');break;}
 case 'save-code':toast('Snippet saved in the current demo session.');break;
 case 'handoff-edit':openModal('Editor hand-off',`<p style="font-size:11px;color:#aab5ba;line-height:1.6">Prepare a project package with source media, proxy files, edit notes and timeline metadata. The actual hand-off requires a configured file-storage and export service.</p><div class="quick-row"><span>CapCut project hand-off</span><span class="status pending">Not connected</span></div><div class="quick-row"><span>DaVinci Resolve project hand-off</span><span class="status pending">Not connected</span></div><button class="btn primary" style="margin-top:14px" id="createHandoff">Create demo hand-off note</button>`);$('#createHandoff').addEventListener('click',()=>{closeModal();toast('Demo hand-off note prepared. No project file exported.','warn');});break;
 case 'export-timeline':toast('Timeline export requires an editing/export backend.','warn');break;
 case 'save-settings':toast('Settings saved to the local demo session.');break;
 }
}
function openCmsEditor(defaultType='Article',initialDraft=null){
 const types=cmsContentTypes;const aligns=contentAlignments;
 openModal('Content editor',`<div class="cms-editor-meta"><label>Content title<input class="field" id="cmsTitle" value="${escapeAttr(initialDraft?.title||'Inside the Production House')}" placeholder="Enter content title"></label><label>Content type<select class="select" id="cmsContentType">${types.map(t=>`<option ${(initialDraft?.type||defaultType)===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Content alignment<select class="select" id="cmsAlignment">${aligns.map(a=>`<option ${(initialDraft?.alignment||'left')===a?'selected':''}>${a}</option>`).join('')}</select></label><label>Status<select class="select" id="cmsStatus">${statusSelectOptions(initialDraft?.status||'Draft')}</select></label></div><div class="editor-toolbar cms-rich-toolbar"><button type="button" data-cms-format="bold"><b>B</b></button><button type="button" data-cms-format="italic"><i>I</i></button><button type="button" data-cms-format="underline"><u>U</u></button><select class="select editor-select" id="cmsFont"><option>Arial</option><option>Georgia</option><option>Verdana</option><option>Times New Roman</option><option>Trebuchet MS</option></select><select class="select editor-select" id="cmsFontSize"><option value="2">13px</option><option value="3" selected>16px</option><option value="4">18px</option><option value="5">24px</option><option value="6">32px</option></select><button type="button" data-cms-format="insertUnorderedList">☷ List</button><button type="button" data-cms-insert="link">↗ URL</button><button type="button" data-cms-insert="image">＋ Image</button><button type="button" data-cms-insert="video">＋ Video</button><button type="button" data-cms-insert="audio">＋ Audio</button><button type="button" data-cms-insert="document">＋ Document</button><button type="button" data-cms-insert="section">＋ Section</button><button type="button" data-cms-insert="page">＋ Page</button><button type="button" data-cms-insert="header">＋ Header</button><button type="button" data-cms-insert="footer">＋ Footer</button><button type="button" data-cms-insert="hero">＋ Hero</button><button type="button" data-cms-insert="news">＋ News feed</button><button type="button" data-cms-insert="blog">＋ Blog</button><button type="button" data-cms-insert="article">＋ Article</button></div><div id="cmsRichEditor" class="cms-rich-editor" contenteditable="true" spellcheck="true">${initialDraft?.html||'<h2>Inside the Production House</h2><p>Write and format your content here. Add images, video, audio, links and reusable content sections.</p>'}</div><div class="cms-editor-foot"><span class="status pending">LOCAL DRAFT</span><span class="helper-text">Formatting and media insertion are browser-side demonstrations.</span></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px"><button class="btn" id="cmsCancel">Cancel</button><button class="btn primary" id="saveContent">Save draft</button></div>`,'CMS CONTENT EDITOR');
 const editor=$('#cmsRichEditor');editor.style.textAlign=alignmentCss($('#cmsAlignment').value).text;$('#cmsAlignment').addEventListener('change',e=>{editor.style.textAlign=alignmentCss(e.target.value).text;});
 $('#modalBody').onclick=e=>{
  const fmt=e.target.closest('[data-cms-format]');if(fmt){editor.focus();document.execCommand(fmt.dataset.cmsFormat,false,null);return;}
  const ins=e.target.closest('[data-cms-insert]');if(ins){const t=ins.dataset.cmsInsert;if(t==='image'||t==='video'||t==='audio'||t==='document'){mediaUploadContext='cms';$('#mediaUpload').accept=t==='document'?'.pdf,.doc,.docx,.ppt,.pptx':'*/*';$('#mediaUpload').click();}else if(t==='link'){const url=prompt('Enter the destination URL','https://');if(url)document.execCommand('createLink',false,url);}else{document.execCommand('insertHTML',false,`<h3>New ${t} block</h3><p>Add your ${t} content here.</p>`);}return;}
 };
 $('#modalBody').onmousedown=e=>{if(e.target.closest('[data-cms-format],[data-cms-insert]'))e.preventDefault();};
 $('#cmsFont').addEventListener('change',e=>{editor.focus();document.execCommand('fontName',false,e.target.value);});
 $('#cmsFontSize').addEventListener('change',e=>{editor.focus();document.execCommand('fontSize',false,e.target.value);});
 $('#cmsCancel').addEventListener('click',closeModal);
 $('#saveContent').addEventListener('click',()=>{const items=store.get('cmsDrafts',[]);const record={title:$('#cmsTitle').value,type:$('#cmsContentType').value,alignment:$('#cmsAlignment').value,status:normalizePublishingStatus($('#cmsStatus').value),html:sanitizeRichHtml(editor.innerHTML),savedAt:new Date().toISOString()};if(Number.isInteger(initialDraft?._index)&&items[initialDraft._index])items[initialDraft._index]=record;else items.unshift(record);store.set('cmsDrafts',items.slice(0,100));closeModal();toast('CMS draft saved in this browser session.');setPage('cms');});
}

function openCmsEditorDraft(index){const items=store.get('cmsDrafts',[]);const draft=items[index];if(!draft)return;openCmsEditor(draft.type||'Article',{...draft,_index:index});}
function openCreateForm(action){const labels={'new-article':'New article','new-submission':'Create news item','new-programme':'New radio programme','new-project':'New production project','new-team':'New team member','new-event':'Create live event','new-playlist':'New video playlist','new-schedule':'Schedule content','invite-creator':'Invite creator','new-edit-project':'New edit project','new-ai-project':'New AI creative project'};const title=labels[action]||'Create item';openModal(title,`<div class="form-grid"><label class="full">Name / title<input class="field" id="createTitle" placeholder="Enter a title"/></label><label>Category<select class="select"><option>General</option><option>Production</option><option>Editorial</option><option>Creative</option><option>Community</option></select></label><label>Status<select class="select">${statusSelectOptions('Draft')}</select></label><label class="full">Description / notes<textarea placeholder="Add a short description..."></textarea></label></div><button class="btn primary" id="createSave" style="margin-top:14px">Save ${title.toLowerCase()}</button>`,'CREATE WORKFLOW');$('#createSave').addEventListener('click',()=>{const v=$('#createTitle').value.trim();if(!v){toast('Enter a title before saving.','warn');return;}closeModal();toast(`${title} “${v}” saved to demo workflow.`);});}
function exportCsv(){const rows=[['Metric','Value','Data classification'],['Website visitors','48250','Demonstration'],['Page views','126840','Demonstration'],['Video views','284600','Demonstration'],['Watch time hours','1348','Demonstration'],['Monthly revenue NGN','850000','Demonstration']];const csv=rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='spp-demo-analytics.csv';a.click();URL.revokeObjectURL(a.href);toast('Demo CSV report exported.');}

$('#mainNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page);});
$('#content').addEventListener('click',e=>{
 const teamEdit=e.target.closest('[data-team-edit]');if(teamEdit){const row=managedTeamRows.find(x=>Number(x.id)===Number(teamEdit.dataset.teamEdit));if(row)openTeamEditor(row);return;}
 const teamDelete=e.target.closest('[data-team-delete]');if(teamDelete){confirmDeleteTeam(teamDelete.dataset.teamDelete);return;}
 const newsEdit=e.target.closest('[data-news-edit]');if(newsEdit){const row=managedNewsRows.find(x=>Number(x.id)===Number(newsEdit.dataset.newsEdit));if(row)openNewsEditor(row);return;}
 const newsDelete=e.target.closest('[data-news-delete]');if(newsDelete){confirmDeleteNews(newsDelete.dataset.newsDelete);return;}
 const syfmMove=e.target.closest('[data-syfm-move]');if(syfmMove){const index=Number(syfmMove.dataset.syfmIndex),delta=syfmMove.dataset.syfmMove==='up'?-1:1,target=index+delta;if(target>=0&&target<syfmSettings.navigation.length){[syfmSettings.navigation[index],syfmSettings.navigation[target]]=[syfmSettings.navigation[target],syfmSettings.navigation[index]];renderSyfmEditor();}return;}
 const syfmRemove=e.target.closest('[data-syfm-remove]');if(syfmRemove){syfmSettings.navigation.splice(Number(syfmRemove.dataset.syfmRemove),1);renderSyfmEditor();return;}
 const page=e.target.closest('[data-page]');if(page){setPage(page.dataset.page);return;}
 const add=e.target.closest('[data-add-section]');if(add){addSection(add.dataset.addSection);return;}
  const savedDraft=e.target.closest('[data-cms-edit-draft]');if(savedDraft){openCmsEditorDraft(Number(savedDraft.dataset.cmsEditDraft));return;}
  const cmsType=e.target.closest('[data-cms-new-type]');if(cmsType){openCmsEditor(cmsType.dataset.cmsNewType);return;}
  const syfmPage=e.target.closest('[data-syfm-page]');if(syfmPage){syfmActivePage=syfmPage.dataset.syfmPage;store.set('syfmActivePage',syfmActivePage);setPage('syfm');return;}
  const syfmCat=e.target.closest('[data-syfm-category]');if(syfmCat){syfmActiveNewsCategory=syfmCat.dataset.syfmCategory;store.set('syfmActiveNewsCategory',syfmActiveNewsCategory);setPage('syfm');return;}
  const builderFmt=e.target.closest('[data-builder-format]');if(builderFmt){if(builderFmt.dataset.builderFormat==='createLink'){const url=prompt('Enter the destination URL','https://');if(url)document.execCommand('createLink',false,url);}else document.execCommand(builderFmt.dataset.builderFormat,false,null);return;}
  const postAction=e.target.closest('[data-post-action]');if(postAction){handlePostAction(postAction);return;}
 const sel=e.target.closest('[data-select-section]');if(sel){selectedSection=Number(sel.dataset.selectSection);setPage('website');return;}
 const device=e.target.closest('[data-device]');if(device){builderDevice=device.dataset.device;setPage('website');return;}
 const action=e.target.closest('[data-action]');if(action){handleAction(action.dataset.action,action);return;}
 const cat=e.target.closest('[data-integration-cat]');if(cat){selectedIntegrationCategory=cat.dataset.integrationCat;setPage('integrations');return;}
 const integ=e.target.closest('[data-integration-id]');if(integ){showIntegration(integ.dataset.integrationId);return;}
 const at=e.target.closest('[data-ai-tab]');if(at){activeStudioTab=at.dataset.aiTab;setPage('ai');return;}
 const media=e.target.closest('[data-media-index]');if(media){const key=media.dataset.mediaIndex;let item;if(key.startsWith('u'))item=mediaItems[Number(key.slice(1))];else{const index=Number(key.slice(1));item=sampleImages[index]||sampleImages[0];}if(item)showMedia(item);return;}
 const vid=e.target.closest('[data-video-index]');if(vid){const item=sampleVideos[Number(vid.dataset.videoIndex)];if(item)showMedia({...item,type:'video',size:'Demo video'});return;}
 const subAdd=e.target.closest('[data-submenu-add]');if(subAdd){const i=Number(subAdd.dataset.submenuAdd),parent=currentMenuItems[i],input=$(`#submenuInput${i}`),value=input?.value.trim();if(value){siteNavSubmenus[parent]=siteNavSubmenus[parent]||[];siteNavSubmenus[parent].push(value);store.set('primarySubmenus',siteNavSubmenus);setPage('menus');toast(`${parent} submenu added.`);}else toast('Enter a submenu label.','warn');return;}
 const subRemove=e.target.closest('[data-submenu-remove]');if(subRemove){const i=Number(subRemove.dataset.submenuRemove),j=Number(subRemove.dataset.submenuIndex),parent=currentMenuItems[i];if(siteNavSubmenus[parent])siteNavSubmenus[parent].splice(j,1);store.set('primarySubmenus',siteNavSubmenus);setPage('menus');return;}
 const navToggle=e.target.closest('[data-site-nav-toggle]');if(navToggle){const group=navToggle.closest('.site-nav-group');const open=group?.classList.toggle('open');navToggle.setAttribute('aria-expanded',String(!!open));return;}
 const navChild=e.target.closest('[data-site-nav-child]');if(navChild){e.preventDefault();return;}
 const navLink=e.target.closest('[data-site-nav-link]');if(navLink){return;}
 const up=e.target.closest('[data-menu-up]');if(up){const i=Number(up.dataset.menuUp);if(i>0){[currentMenuItems[i-1],currentMenuItems[i]]=[currentMenuItems[i],currentMenuItems[i-1]];store.set('primaryMenuItems',currentMenuItems);setPage('menus');}return;}
 const down=e.target.closest('[data-menu-down]');if(down){const i=Number(down.dataset.menuDown);if(i<currentMenuItems.length-1){[currentMenuItems[i+1],currentMenuItems[i]]=[currentMenuItems[i],currentMenuItems[i+1]];store.set('primaryMenuItems',currentMenuItems);setPage('menus');}return;}
 const rem=e.target.closest('[data-menu-remove]');if(rem){const idx=Number(rem.dataset.menuRemove),parent=currentMenuItems[idx];currentMenuItems.splice(idx,1);delete siteNavSubmenus[parent];store.set('primaryMenuItems',currentMenuItems);store.set('primarySubmenus',siteNavSubmenus);setPage('menus');return;}
});

$('#content').addEventListener('input',e=>{
 if(e.target.matches('#newsAdminSearch')){renderManagedNewsRows();return;}
 const body=e.target.closest('[data-builder-edit]');if(body){const id=Number(body.dataset.builderEdit),sec=builderSections.find(x=>x.id===id);if(sec){sec.bodyHtml=sanitizeRichHtml(body.innerHTML);sec.body=body.innerText;store.set('builderSections',builderSections);}return;}
 const title=e.target.closest('[data-builder-title]');if(title){const id=Number(title.dataset.builderTitle),sec=builderSections.find(x=>x.id===id);if(sec){sec.title=title.innerText;sec.titleHtml=sanitizeRichHtml(title.innerHTML);store.set('builderSections',builderSections);}return;}
});
$('#content').addEventListener('mousedown',e=>{if(e.target.closest('[data-builder-format]'))e.preventDefault();});
$('#content').addEventListener('change',e=>{if(e.target.matches('#newsStatusFilter'))renderManagedNewsRows();});

$('#mediaUpload').addEventListener('change',e=>{
 const files=[...e.target.files||[]];if(!files.length)return;
 const context=mediaUploadContext;mediaUploadContext='library';
 if(context==='builder'){
  const file=files[0],isDoc=/\.(pdf|docx?|pptx?)$/i.test(file.name),type=isDoc?'document':file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image',url=URL.createObjectURL(file);const sec=builderSections.find(x=>x.id===selectedSection);if(sec){sec.mediaUrl=url;sec.mediaType=type;sec.fileName=file.name;store.set('builderSections',builderSections);}for(const f of files.slice(1)){const t=/\.(pdf|docx?|pptx?)$/i.test(f.name)?'document':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'image';mediaItems.unshift({name:f.name,type:t,size:(f.size/1024/1024).toFixed(2)+' MB',category:'Builder attachment',src:URL.createObjectURL(f),views:'0',local:true});}setPage('website');toast('Media attached to the selected page block for local preview.','warn');
 }else if(context==='cms'){
  const editor=$('#cmsRichEditor');if(editor){for(const file of files){const isDoc=/\.(pdf|docx?|pptx?)$/i.test(file.name),type=isDoc?'document':file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'image',url=URL.createObjectURL(file);const html=type==='document'?`<p><a href="${url}" target="_blank" rel="noopener">▤ ${escapeHtml(file.name)}</a></p>`:type==='video'?`<video controls src="${url}" style="max-width:100%"></video>`:type==='audio'?`<audio controls src="${url}"></audio>`:`<img src="${url}" alt="${escapeAttr(file.name)}" style="max-width:100%">`;editor.focus();document.execCommand('insertHTML',false,html+'<p></p>');}}toast('Media inserted into the CMS editor for this browser session.','warn');
 }else{
  for(const f of files){const type=/\.(pdf|docx?|pptx?)$/i.test(f.name)?'document':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':'image';mediaItems.unshift({name:f.name,type,size:(f.size/1024/1024).toFixed(2)+' MB',category:'Uploaded locally',src:URL.createObjectURL(f),views:'0',local:true});}store.set('mediaItems',mediaItems.map(m=>({...m,src:m.local?'':m.src})));setPage('media');toast(`${files.length} file(s) added for local preview. Not uploaded to a server.`,'warn');
 }
 e.target.value='';$('#mediaUpload').accept='image/*,video/*,audio/*,.pdf,.doc,.docx,.ppt,.pptx';
});
$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();}});
$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase();const hit=Object.entries(pageNames).find(([k,v])=>(k+' '+v).toLowerCase().includes(q));if(hit)setPage(hit[0]);else toast('No matching workspace found.','warn');}});
const greetingName=document.getElementById('adminGreetingName');if(greetingName)greetingName.textContent=`Administrator (${ADMIN_NAME})`;
const profileName=document.getElementById('profileAdminName');if(profileName)profileName.textContent=ADMIN_NAME;
const profileRole=document.getElementById('profileAdminRole');if(profileRole)profileRole.textContent=ADMIN_ROLE;
const avatar=document.getElementById('profileAvatar');if(avatar)avatar.textContent=ADMIN_NAME.split(/\s+/).filter(x=>/^[A-Z]/i.test(x)).slice(0,2).map(x=>x[0].toUpperCase()).join('');
checkApiHealth();window.setInterval(checkApiHealth,Number(window.SPP_CONFIG?.HEALTH_CHECK_INTERVAL_MS)||30000);
setPage('overview');
